import { Filter } from 'glin-profanity';

// src/mcp.ts
function createFilter(config) {
  return new Filter({
    languages: config?.languages || ["english"],
    detectLeetspeak: config?.detectLeetspeak ?? true,
    normalizeUnicode: config?.normalizeUnicode ?? true,
    severityLevels: true,
    cacheResults: true,
    ...config
  });
}
var checkProfanityMCPTool = {
  name: "check_profanity",
  description: "Check text for profanity in 24 languages. Detects leetspeak and unicode obfuscation.",
  inputSchema: {
    type: "object",
    properties: {
      text: {
        type: "string",
        description: "The text to check for profanity"
      },
      languages: {
        type: "array",
        description: 'Languages to check (default: ["english"])',
        items: { type: "string" }
      },
      detectLeetspeak: {
        type: "boolean",
        description: "Whether to detect leetspeak variations (default: true)",
        default: true
      }
    },
    required: ["text"]
  }
};
var censorTextMCPTool = {
  name: "censor_text",
  description: "Censor profanity in text by replacing bad words with asterisks or custom replacement.",
  inputSchema: {
    type: "object",
    properties: {
      text: {
        type: "string",
        description: "The text to censor"
      },
      replacement: {
        type: "string",
        description: 'Replacement string for profanity (default: "***")',
        default: "***"
      },
      languages: {
        type: "array",
        description: "Languages to check",
        items: { type: "string" }
      }
    },
    required: ["text"]
  }
};
var batchCheckMCPTool = {
  name: "batch_check_profanity",
  description: "Check multiple texts for profanity at once. Efficient for bulk processing.",
  inputSchema: {
    type: "object",
    properties: {
      texts: {
        type: "array",
        description: "Array of texts to check",
        items: { type: "string" }
      },
      languages: {
        type: "array",
        description: "Languages to check",
        items: { type: "string" }
      }
    },
    required: ["texts"]
  }
};
var analyzeContextMCPTool = {
  name: "analyze_profanity_context",
  description: "Analyze profanity with context awareness. Understands when words are used appropriately.",
  inputSchema: {
    type: "object",
    properties: {
      text: {
        type: "string",
        description: "The text to analyze"
      },
      contextWindow: {
        type: "number",
        description: "Number of words to consider for context (default: 3)",
        default: 3
      },
      languages: {
        type: "array",
        description: "Languages to check",
        items: { type: "string" }
      }
    },
    required: ["text"]
  }
};
var getSupportedLanguagesMCPTool = {
  name: "get_supported_languages",
  description: "Get list of all 24 supported languages for profanity detection.",
  inputSchema: {
    type: "object",
    properties: {}
  }
};
var mcpTools = [
  checkProfanityMCPTool,
  censorTextMCPTool,
  batchCheckMCPTool,
  analyzeContextMCPTool,
  getSupportedLanguagesMCPTool
];
async function executeMCPTool(toolName, args) {
  switch (toolName) {
    case "check_profanity": {
      const filter = createFilter({
        languages: args.languages || ["english"],
        detectLeetspeak: args.detectLeetspeak ?? true
      });
      const result = filter.checkProfanity(args.text);
      return {
        content: [{
          type: "text",
          text: JSON.stringify({
            containsProfanity: result.containsProfanity,
            profaneWords: result.profaneWords,
            processedText: result.processedText,
            matches: result.matches
          }, null, 2)
        }]
      };
    }
    case "censor_text": {
      const filter = createFilter({
        languages: args.languages || ["english"],
        replaceWith: args.replacement || "***"
      });
      const result = filter.checkProfanity(args.text);
      return {
        content: [{
          type: "text",
          text: JSON.stringify({
            originalText: args.text,
            censoredText: result.processedText,
            wordsCensored: result.profaneWords.length,
            profaneWords: result.profaneWords
          }, null, 2)
        }]
      };
    }
    case "batch_check_profanity": {
      const filter = createFilter({
        languages: args.languages || ["english"]
      });
      const texts = args.texts;
      const results = texts.map((text, index) => {
        const result = filter.checkProfanity(text);
        return {
          index,
          text: text.substring(0, 50) + (text.length > 50 ? "..." : ""),
          containsProfanity: result.containsProfanity,
          profaneWords: result.profaneWords
        };
      });
      const flaggedCount = results.filter((r) => r.containsProfanity).length;
      return {
        content: [{
          type: "text",
          text: JSON.stringify({
            totalChecked: texts.length,
            flaggedCount,
            cleanCount: texts.length - flaggedCount,
            results
          }, null, 2)
        }]
      };
    }
    case "analyze_profanity_context": {
      const filter = createFilter({
        languages: args.languages || ["english"],
        enableContextAware: true,
        contextWindow: args.contextWindow || 3
      });
      const result = filter.checkProfanity(args.text);
      return {
        content: [{
          type: "text",
          text: JSON.stringify({
            containsProfanity: result.containsProfanity,
            profaneWords: result.profaneWords,
            matches: result.matches?.map((m) => ({
              word: m.word,
              index: m.index,
              severity: m.severity,
              contextScore: m.contextScore,
              isWhitelisted: m.isWhitelisted,
              reason: m.reason
            })),
            analysis: {
              totalMatches: result.matches?.length || 0,
              whitelisted: result.matches?.filter((m) => m.isWhitelisted).length || 0,
              flagged: result.matches?.filter((m) => !m.isWhitelisted).length || 0
            }
          }, null, 2)
        }]
      };
    }
    case "get_supported_languages": {
      const languages = [
        "arabic",
        "chinese",
        "czech",
        "danish",
        "dutch",
        "english",
        "esperanto",
        "finnish",
        "french",
        "german",
        "hindi",
        "hungarian",
        "italian",
        "japanese",
        "korean",
        "norwegian",
        "persian",
        "polish",
        "portuguese",
        "russian",
        "spanish",
        "swedish",
        "thai",
        "turkish"
      ];
      return {
        content: [{
          type: "text",
          text: JSON.stringify({
            count: languages.length,
            languages,
            note: "Pass languages array to other tools to filter specific languages."
          }, null, 2)
        }]
      };
    }
    default:
      return {
        content: [{
          type: "text",
          text: `Unknown tool: ${toolName}`
        }],
        isError: true
      };
  }
}
function createMCPHandler() {
  return {
    /** List all available tools */
    listTools: () => mcpTools,
    /** Get a specific tool definition */
    getTool: (name) => mcpTools.find((t) => t.name === name),
    /** Execute a tool */
    executeTool: (name, args) => executeMCPTool(name, args),
    /** Server info */
    getServerInfo: () => ({
      name: "glin-profanity-mcp",
      version: "1.0.0",
      description: "Content moderation MCP server with 24-language profanity detection",
      capabilities: {
        tools: mcpTools.map((t) => t.name)
      }
    })
  };
}
var mcpServerConfig = {
  name: "glin-profanity",
  description: "Content moderation with 24-language profanity detection",
  version: "1.0.0",
  tools: mcpTools.map((t) => t.name)
};

export { analyzeContextMCPTool, batchCheckMCPTool, censorTextMCPTool, checkProfanityMCPTool, createMCPHandler, executeMCPTool, getSupportedLanguagesMCPTool, mcpServerConfig, mcpTools };
